-- READ-ONLY per-archive row presence for 2016–2017 strict paired source-only candidate cohort.
WITH c AS (SELECT o.dateTime FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime WHERE o.dateTime>=1451606400 AND o.dateTime<1514764800 AND r.dateTime IS NULL AND o.dateTime%300=0 AND o.usUnits=17 AND w.usUnits=17 AND o.`interval`=5 AND w.`interval`=5) SELECT CASE WHEN c.dateTime<1483228800 THEN 2016 ELSE 2017 END utc_year,COUNT(*) cohort_rows,SUM(r.dateTime IS NOT NULL) reconstruction_rows,SUM(e.dateTime IS NOT NULL) pocasi_eu_rows,SUM(g.dateTime IS NOT NULL) gw1000_rows,SUM(eo.dateTime IS NOT NULL) eu_old_rows,SUM(o.dateTime IS NOT NULL) old_weewx_rows,SUM(w.dateTime IS NOT NULL) wh1080_rows FROM c LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=c.dateTime LEFT JOIN `pocasi-loucka.eu`.archive e ON e.dateTime=c.dateTime LEFT JOIN `pocasi-loucka.eu_GW1000`.archive g ON g.dateTime=c.dateTime LEFT JOIN `pocasi-loucka.eu_old`.archive eo ON eo.dateTime=c.dateTime LEFT JOIN old_weewx.archive o ON o.dateTime=c.dateTime LEFT JOIN weewx_WH1080.archive w ON w.dateTime=c.dateTime GROUP BY utc_year ORDER BY utc_year;
